void HashMgr::free_table() {
  // now pass through hash table freeing up everything
  // go through column by column of the table
  for (auto ptr : tableptr) {
    hentry* nt = NULL;
    while (ptr) {
      nt = ptr->next;
      free_flag(ptr->astr, ptr->alen);
      free(ptr);
      ptr = nt;
    }
  }
  tableptr.clear();
}

